b.setColor(0x44000000);c.drawOval(-20,79,20,89,b);float step=(float)Math.sin(walk)*9;line(c,0xff303b4b,-7,49,-9+step,76,11);line(c,0xff303b4b,7,49,9-step,76,11);box(c,0xff171d25,-15+step,74,15,7,3);box(c,0xff171d25,3-step,74,15,7,3);
box(c,shirt,-17,13,34,42,9);box(c,0x33000000,-17,40,34,15,4);line(c,shirt,-15,20,-23,39+step*.3f,10);line(c,shirt,15,20,23,38-step*.3f,10);dot(c,face,-23,42+step*.3f,5);dot(c,face,23,41-step*.3f,5);box(c,face,-5,6,10,12,3);dot(c,face,-13,-1,4);dot(c,face,13,-1,4);box(c,face,-13,-17,26,31,12);box(c,hair,-14,-20,28,12,6);if(id%3==1)box(c,hair,-16,-13,5,23,3);dot(c,0xff27242a,-5,-1,1.7f);dot(c,0xff27242a,5,-1,1.7f);if(seller&&expression!=0){b.setColor(0xff8c493a);b.setStyle(Paint.Style.STROKE);b.setStrokeWidth(1.8f);c.drawArc(-6,expression>0?0:7,6,expression>0?11:16,expression>0?0:180,180,false,b);b.setStyle(Paint.Style.FILL);if(expression<0){line(c,0xff392b26,-9,-7,-3,-4,1.6f);line(c,0xff392b26,3,-4,9,-7,1.6f);}}else line(c,0xff995e49,-3,7,3,7,1.5f);if(id%4==2){box(c,0x55333333,-10,-5,9,8,2);box(c,0x55333333,1,-5,9,8,2);line(c,0xff333333,-1,-2,1,-2,1);}
